dofile"util.lua"
local function lvl2(a, b, ...)
  local c = a + b
  local info = debug.getinfo(1)
  dumpt(info, "  ")
  print("---")
  dumpt(debug.getinfo(2, "nSl"), "  ")
  print(debug.getlocal(1, 1), debug.getlocal(1, 2), debug.getlocal(1, 3), debug.getlocal(1, 4), debug.getlocal(1, -1), debug.getlocal(1, -2), debug.getlocal(1, -3))
  print(debug.setlocal(1, 3, 100), c, debug.setlocal(1, 10, 1), debug.setlocal(1, -1, "va"))
  print(...)
  return c
end
